--
-- Table structure for table `borrow_histories`
--

CREATE TABLE `borrow_histories` (
  `id` int NOT NULL,
  `recordId` varchar(255) NOT NULL,
  `borrowerName` varchar(255) NOT NULL,
  `equipmentId` varchar(255) NOT NULL,
  `equipmentName` varchar(255) NOT NULL,
  `borrowDate` date NOT NULL,
  `returnDate` date DEFAULT NULL,
  `condition` varchar(255) DEFAULT NULL,
  `purpose` text,
  `remarks` text,
  `processedBy` varchar(255) DEFAULT NULL,
  `eventType` varchar(255) NOT NULL DEFAULT 'borrowed',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `borrowStartTime` varchar(255) DEFAULT NULL,
  `expectedReturnTime` varchar(255) DEFAULT NULL,
  `equipment_record_id` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

