-- --------------------------------------------------------

--
-- Table structure for table `equipment`
--

CREATE TABLE `equipment` (
  `equipmentId` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `assetNumber` varchar(255) DEFAULT NULL,
  `category` varchar(255) NOT NULL,
  `campus` varchar(255) NOT NULL,
  `laboratoryRoom` varchar(255) DEFAULT NULL,
  `qrCode` text,
  `qrImage` longtext,
  `qrGeneratedAt` datetime DEFAULT NULL,
  `status` enum('Serviceable','Unserviceable','Lost','Missing','Under Maintenance') NOT NULL DEFAULT 'Serviceable',
  `dateAdded` date NOT NULL,
  `quantity` int NOT NULL DEFAULT '1',
  `id` int NOT NULL,
  `serialNumber` varchar(100) DEFAULT NULL COMMENT 'Unique serial number for equipment identification',
  `setId` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturer` varchar(100) DEFAULT NULL COMMENT 'Equipment manufacturer',
  `model` varchar(100) DEFAULT NULL COMMENT 'Equipment model number',
  `purchaseDate` date DEFAULT NULL COMMENT 'Date equipment was purchased',
  `warrantyExpiry` date DEFAULT NULL COMMENT 'Warranty expiration date',
  `condition` enum('excellent','good','fair','poor','broken') DEFAULT 'good' COMMENT 'Current physical condition',
  `location` varchar(255) DEFAULT NULL COMMENT 'Current physical location in lab',
  `remarks` text COMMENT 'Additional notes about the equipment',
  `missingReportedAt` datetime DEFAULT NULL COMMENT 'When equipment was reported missing',
  `missingReportedBy` int DEFAULT NULL COMMENT 'User ID who reported it missing',
  `missingReason` text COMMENT 'Reason/notes for missing report',
  `foundAt` datetime DEFAULT NULL COMMENT 'When missing equipment was marked found',
  `foundBy` int DEFAULT NULL COMMENT 'User ID who marked it as found'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

